from taf.internal.managedobject import ManagedObject
from taf.ue.spark.api.executor import TCPExecutor
from taf.ue.spark.api.command import (
    AutoCheck, ConnectEQ, DisConnectEQ, StartLog, StopLog, StartULtraffic, StopULtraffic,
    Attach, Detach, PowerOn, PowerOff, LockBand, UnlockBand,
    Config5GDeployment, GetParamMAC, GetParamIMSI, GetPDUInfo, ExportMessageDetail,
    ExportLogfile, ConfigureAPN, SetupPDU, ReleasePDU, Config5GNRmeasurementAndEvent, SendAT, SetupS_NSSAI,
    TurnOnMobileData, TurnOffMobileData, ConnectOneEQ, DisConnectOneEQ, StartOneLog, StopOneLog, GetParamValue)


class Spark(ManagedObject):
    def __init__(self, host, port=None):
        super(Spark, self).__init__()
        self._supported_commands = [
            AutoCheck, ConnectEQ, DisConnectEQ, StartLog, StopLog, StartULtraffic, StopULtraffic,
            Attach, Detach, PowerOn, PowerOff, LockBand, UnlockBand,
            Config5GDeployment, GetParamMAC, GetParamIMSI, GetPDUInfo, ExportMessageDetail,
            ExportLogfile, ConfigureAPN, SetupPDU, ReleasePDU, Config5GNRmeasurementAndEvent,
            SendAT, SetupS_NSSAI, TurnOnMobileData, TurnOffMobileData, ConnectOneEQ, DisConnectOneEQ,
            StartOneLog, StopOneLog, GetParamValue
        ]

        self._host = host
        self._port = port or 30999

        self._executor = TCPExecutor(self._host, self._port, default_retry_timeout=60)
        self._commands = []
        self._initialize_commands()

    @property
    def commands(self):
        return self._commands

    @property
    def host(self):
        return self._host

    @property
    def port(self):
        return self._port

    def _setup(self):
        self._executor.connect()

    def _teardown(self):
        self._executor.disconnect()

    def _initialize_commands(self):
        for command_cls in self._supported_commands:
            command = command_cls(self._executor)
            setattr(self, command_cls.__name__, command)
            self._commands.append(command)
